/** Built-in dual-mode theme families shipped with the Appearance library. */

import {
  DEFAULT_CONTRAST, DEFAULT_FAMILY_ID, type ThemeFamily, type ThemeSeeds, type ThemeSkinId,
} from './theme-family.ts'

function seeds(
  accent: string,
  background: string,
  foreground: string,
  contrast = DEFAULT_CONTRAST,
  overrides?: Record<string, string>,
): ThemeSeeds {
  return { accent, background, foreground, contrast, ...(overrides === undefined ? {} : { overrides }) }
}

function family(
  id: string,
  name: string,
  light: ThemeSeeds,
  dark: ThemeSeeds,
  skin: ThemeSkinId = 'default',
  wallpaper?: string,
): ThemeFamily {
  return { id, name, origin: 'builtin', skin, ...(wallpaper === undefined ? {} : { wallpaper }), light, dark }
}

/**
 * Product default: empty derived tokens so the CSS sheets stay authoritative.
 * Seed colors still drive the library swatches.
 */
export const DEEPSEEK_FAMILY: ThemeFamily = family(
  DEFAULT_FAMILY_ID,
  'DeepSeek',
  seeds('#4176e6', '#ffffff', '#0f1115', 46),
  seeds('#6ea8ff', '#151517', '#f5f5f5', 41),
)

