/** Warm-paper Claude family; prose typography and edges come from `skins.css`. */
export const CLAUDE_FAMILY: ThemeFamily = family(
  'claude',
  'Claude',
  seeds('#c96442', '#faf9f5', '#262624', 44, CLAUDE_LIGHT_OVERRIDES),
  seeds('#d97757', '#262624', '#f5f4ef', 55, CLAUDE_DARK_OVERRIDES),
  'claude',
)

